import{_ as r,o as e,c as d,a2 as a}from"./chunks/framework.CWWEQfK7.js";const p=JSON.parse('{"title":"先决定要启用什么","description":"从登录、分析、Wiki、搜索、MCP 和自动更新出发，找到每项能力真正依赖的服务与设置。","frontmatter":{"page_id":"configuration-features","title":"先决定要启用什么","description":"从登录、分析、Wiki、搜索、MCP 和自动更新出发，找到每项能力真正依赖的服务与设置。"},"headers":[],"relativePath":"configuration/index.md","filePath":"configuration/index.md","lastUpdated":1786627803000}'),o={name:"configuration/index.md"};function i(l,t,n,h,s,c){return e(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="先决定要启用什么" tabindex="-1">先决定要启用什么 <a class="header-anchor" href="#先决定要启用什么" aria-label="Permalink to &quot;先决定要启用什么&quot;">​</a></h1><p>不要从环境变量参考表开始读。先确定这台 Ershu 要提供登录、分析、Wiki、语义搜索、MCP 还是自动更新，再检查对应的进程和依赖。</p><p>Core、API、Worker、MCP 和前端各自负责不同部分。同名设置不会自动在多台主机之间同步，部署者仍要让相关进程拿到一致的值。</p><h2 id="先认清三类设置" tabindex="-1">先认清三类设置 <a class="header-anchor" href="#先认清三类设置" aria-label="Permalink to &quot;先认清三类设置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>典型内容</th><th>何时读取</th><th>修改方式</th></tr></thead><tbody><tr><td>启动必需项</td><td>数据库地址、加密密钥、监听地址</td><td>进程启动时</td><td>环境变量或环境文件；通常需要重启</td></tr><tr><td>可在线管理项</td><td>Worker 并发、预算、检索限制、依赖来源</td><td>服务运行期间</td><td>管理界面或管理 API；数据库值可覆盖启动值</td></tr><tr><td>前端构建项</td><td>API 基础地址、开发代理地址</td><td>构建或启动前端时</td><td><code>VITE_</code> 环境变量；改动后重新构建</td></tr></tbody></table><p>Core 是共享包，不是独立进程。API、Worker 和 MCP 都会读取 Core 的数据库、安全与检索设置；同名设置不代表每个进程会自动共享环境，部署时仍要保证需要它的进程拿到一致值。</p><h2 id="功能与依赖关系" tabindex="-1">功能与依赖关系 <a class="header-anchor" href="#功能与依赖关系" aria-label="Permalink to &quot;功能与依赖关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想启用的能力</th><th>参与模块</th><th>必要条件</th><th>怎样确认</th></tr></thead><tbody><tr><td>登录和网页管理</td><td>API、前端、Core</td><td>PostgreSQL、会话和 OPAQUE 密钥、正确的跨域设置</td><td>能完成首位管理员注册并读取当前用户</td></tr><tr><td>仓库与项目管理</td><td>API、前端、Core</td><td>项目权限；远程仓库还需要对应凭据</td><td>仓库验证通过，项目详情显示当前仓库</td></tr><tr><td>全项目与增量分析</td><td>API、Worker、Core</td><td>PostgreSQL、运行中的 Worker、可读仓库；生成文档还需要模型通道</td><td>任务从排队进入运行，并以明确结果结束</td></tr><tr><td>词法搜索</td><td>API、Worker、Core、前端</td><td>已完成的代码索引</td><td>搜索结果包含仓库、路径和来源位置</td></tr><tr><td>语义搜索</td><td>API、Worker、Core、前端</td><td>Milvus、嵌入模型设置、已构建的搜索索引</td><td>结果说明实际使用了语义或混合模式</td></tr><tr><td>项目文档与问答</td><td>API、Worker、Core、前端</td><td>已启用的模型通道、已完成的文档</td><td>文档可打开，问答返回可查看的引用</td></tr><tr><td>MCP 查询</td><td>MCP、Core</td><td>PostgreSQL、MCP 服务认证、项目范围密钥</td><td>客户端能列出允许访问的项目并读取上下文</td></tr><tr><td>定时与 Webhook 更新</td><td>API、Worker、Core</td><td>轮询进程或签名密钥、运行中的 Worker</td><td>新任务出现，并记录触发来源和目标提交</td></tr></tbody></table><h2 id="分析能力需要什么" tabindex="-1">分析能力需要什么？ <a class="header-anchor" href="#分析能力需要什么" aria-label="Permalink to &quot;分析能力需要什么？&quot;">​</a></h2><p>API 负责验证请求并创建运行记录，Core 把任务和状态写入 PostgreSQL，Worker 再领取任务。Redis 用于短期缓存和分布式协调，但它不代替持久任务队列。仅启动 API 不会执行分析。</p><p>生成项目文档依赖模型通道。管理员通过网页或 API 分别创建、测试和启用模型通道；这些设置不会收进环境文件里的一个通用密钥。Worker 领取任务时读取选定通道，并按任务预算调用模型。</p><p>首次运行必须覆盖项目中的所有有效仓库。完成基线后，才可以针对变更提交创建增量任务。这个限制由 API 校验，不应通过直接改数据库绕过。</p><h2 id="检索能力需要什么" tabindex="-1">检索能力需要什么？ <a class="header-anchor" href="#检索能力需要什么" aria-label="Permalink to &quot;检索能力需要什么？&quot;">​</a></h2><p>词法搜索读取已经生成的代码索引。语义搜索还需要 Milvus 和有效的嵌入设置；混合搜索会组合两类结果。</p><p>请把“服务能启动”和“检索已就绪”分开验证：</p><ol><li>确认 Milvus 可以连接；</li><li>确认嵌入模型设置有效；</li><li>确认目标项目已经完成包含搜索索引的分析；</li><li>发起一次带明确模式的查询，检查响应中报告的实际模式和回退原因。</li></ol><p>语义模式出错时不会静默返回词法结果。混合模式在特定失败下可以明确回退，因此调用方应读取响应状态，而不是只看是否有结果。</p><h2 id="访问与自动化需要什么" tabindex="-1">访问与自动化需要什么？ <a class="header-anchor" href="#访问与自动化需要什么" aria-label="Permalink to &quot;访问与自动化需要什么？&quot;">​</a></h2><p>网页登录使用 OPAQUE 密码流程和会话 Cookie。会改变状态的浏览器请求还受 CSRF 与来源检查保护。MCP 使用 Bearer 凭据，密钥带项目范围；两套入口不要共用凭据。</p><p>远程仓库凭据经过应用层加密后保存。加密密钥、会话密钥、MCP 密钥哈希密钥和 Webhook 签名密钥都应使用彼此独立的随机值。轮换前先阅读<a href="/configuration/security">权限与安全</a>，因为部分密钥变化会使已有数据或会话失效。</p><p>定时轮询由单独的 <code>ershu-api-poller</code> 进程执行。Webhook 则由 API 验证时间戳、随机数和原始请求体的签名。两种方式都只负责创建任务，后续仍依赖 Worker。</p><h2 id="接下来读什么" tabindex="-1">接下来读什么 <a class="header-anchor" href="#接下来读什么" aria-label="Permalink to &quot;接下来读什么&quot;">​</a></h2><ol><li>用<a href="/configuration/basic">基础配置</a>从部署示例改出第一份可用配置；</li><li>用<a href="/configuration/loading-and-overrides">加载与覆盖规则</a>确认哪个值真正生效；</li><li>按<a href="/configuration/services">模块配置</a>准备每个进程；</li><li>在<a href="/configuration/environment-reference">环境变量参考</a>查类型、默认值和限制；</li><li>上线前完成<a href="/configuration/security">权限与安全</a>清单；</li><li>失败时按<a href="/configuration/troubleshooting">配置故障排查</a>定位。</li></ol>',23)])])}const u=r(o,[["render",i]]);export{p as __pageData,u as default};
